package com.aaliyun.leadnews.wemedia.audit;
import com.aaliyun.leadnews.common.exception.BusinessException;import com.aaliyun.leadnews.model.ai.ArticleAuditRequest;import com.aaliyun.leadnews.model.foundation.ArticleContentItemDTO;import com.aaliyun.leadnews.wemedia.domain.*;import com.aaliyun.leadnews.wemedia.mapper.*;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Component;import java.util.*;
@Component public class AuditRequestFactory {private final WmNewsMaterialMapper links;private final WmMaterialMapper materials;private final ObjectMapper json;public AuditRequestFactory(WmNewsMaterialMapper l,WmMaterialMapper m,ObjectMapper j){links=l;materials=m;json=j;}
 public ArticleAuditRequest create(WmNews n){try{List<ArticleContentItemDTO>items=json.readValue(n.getContent(),new TypeReference<>(){});String text=items.stream().filter(i->"text".equalsIgnoreCase(i.type())).map(ArticleContentItemDTO::value).filter(Objects::nonNull).reduce("",(a,b)->a.isEmpty()?b:a+"\n"+b);List<String> imageRefs=new ArrayList<>(items.stream().filter(i->"image".equalsIgnoreCase(i.type())).map(ArticleContentItemDTO::value).filter(Objects::nonNull).toList());List<String> covers=json.readValue(n.getCoverImages(),new TypeReference<>(){});imageRefs.addAll(covers);List<WmNewsMaterial>refs=links.selectList(new LambdaQueryWrapper<WmNewsMaterial>().eq(WmNewsMaterial::getNewsId,n.getId()).orderByAsc(WmNewsMaterial::getOrd));Map<String,String>known=new HashMap<>();for(WmNewsMaterial ref:refs){WmMaterial m=materials.selectById(ref.getMaterialId());if(m!=null&&m.getUrl()!=null&&m.getObjectKey()!=null)known.put(m.getUrl(),m.getObjectKey());}List<String>keys=new ArrayList<>();for(String image:imageRefs){String key=known.get(image);if(key==null)throw new BusinessException(42211,"Article image is not a trusted material object");keys.add(key);}return new ArticleAuditRequest(n.getId(),n.getAuditVersion(),n.getTitle(),n.getLabels(),text,List.copyOf(new LinkedHashSet<>(keys)));}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException(42212,"Stored article content cannot be audited safely");}}
}
